#include <stdio.h>

int compare(const char *a, const char *b) {
    int i = 0;
    while (a[i] != '\0' && a[i] == b[i]) {
        i++;
    }
    return a[i] - b[i];
}

int main() {
    const char *words[] = {"cat", "car", "cab"};
    for (int i = 0; i < 2; i++) {
        int r = compare(words[i], words[i + 1]);
        const char *verdict = r > 0 ? "after" : r < 0 ? "before" : "same";
        printf("%s vs %s: %s\n", words[i], words[i + 1], verdict);
    }
    return 0;
}
